package com.gomgomapps.math.core;
import java.util.*;import java.util.regex.*;
/** Both scaled terms are entered as integers; equivalent reduced forms cannot replace the requested rewrite. */
public final class EquivalentFractionScaling {
 private EquivalentFractionScaling(){}
 public static final String ID="equivalentFractionScaling";
 public static final Catalog.Skill SKILL=new Catalog.Skill(ID,"분자와 분모에 같은 수 곱하기",6,1,1,"",ID,1200,"tables,fractionPart","분자와 분모에 같은 양의 정수를 곱하면 분수의 크기는 같다.");
 private static final Pattern P=Pattern.compile("^([0-9]{1,7})/([0-9]{1,7}) = \\(([0-9]{1,7}) × ([0-9]{1,3})\\)/\\(([0-9]{1,7}) × ([0-9]{1,3})\\) = □/□\\n분자와 분모에 같은 수를 곱해 두 빈칸을 쓰세요\\.$");
 public static int[] read(Question q){if(q==null||!ID.equals(q.skillId)||q.prompt==null)return null;Matcher m=P.matcher(q.prompt);if(!m.matches()||!m.group(1).equals(m.group(3))||!m.group(2).equals(m.group(5))||!m.group(4).equals(m.group(6)))return null;int n=Integer.parseInt(m.group(1)),d=Integer.parseInt(m.group(2)),k=Integer.parseInt(m.group(4));if(d==0||k==0||n>1000000||d>1000000||k>100||(long)n*k>1000000||(long)d*k>1000000)return null;return new int[]{n,d,k,n*k,d*k};}
 static Question make(int n,int d,int k){Question q=new Question(ID,n+"/"+d+" = ("+n+" × "+k+")/("+d+" × "+k+") = □/□\n분자와 분모에 같은 수를 곱해 두 빈칸을 쓰세요.","");int[]v=read(q);if(v==null)throw new IllegalArgumentException("fraction scaling domain");q.answers=new String[]{""+v[3],""+v[4]};q.labels=new String[]{"곱한 분자","곱한 분모"};q.kind="fractionScaling";q.stepSupport=false;attach(q);return q;}
 static Question next(Random random,CurriculumLimits limits,Map<String,Integer>recent){int max=limits.givenMaximum(100),factor=Math.min(12,max);if(max<2)throw new IllegalArgumentException("fraction scaling practice range");long size=(max+1L)*max*(factor-1);return IndexedQuestionSupply.chooseLarge(size,index->{int k=2+(int)(index%(factor-1));index/=factor-1;int d=1+(int)(index%max),n=(int)(index/max);return make(n,d,k);},random,limits,recent);}
 public static void attach(Question q){int[]v=read(q);if(v==null)return;StudyGuide g=new StudyGuide().transfer(false);g.teachingVersion="equivalent-fraction-scaling-v1";String[]instructions={"원래 분자를 쓰세요.","원래 분모를 쓰세요.","분자와 분모에 똑같이 곱할 수를 쓰세요.","원래 분자에 같은 수를 곱하세요.","원래 분모에도 같은 수를 곱하세요."};String[]before={"원래 분자 = ","원래 분모 = ","같은 인수 = ",v[0]+" × "+v[2]+" = ",v[1]+" × "+v[2]+" = "};for(int i=0;i<5;i++)g.step(instructions[i],before[i],"",""+v[i]);q.studyGuide=g;}
 static Checker.Result check(Question q,List<String>answers){int[]v=read(q);if(v==null||answers==null||answers.size()!=2)return new Checker.Result(Checker.Status.INPUT_NEEDED,-1,"곱한 분자와 분모 입력 필요");for(int i=0;i<2;i++){String s=answers.get(i);if(s==null||!s.trim().matches("[0-9]{1,7}"))return new Checker.Result(Checker.Status.INPUT_NEEDED,i,"곱한 분자와 분모 입력 필요");if(Integer.parseInt(s.trim())!=v[i+3])return new Checker.Result(Checker.Status.WRONG_ANSWER,i,i==0?"곱한 분자 다시 확인":"곱한 분모 다시 확인");}return new Checker.Result(Checker.Status.CORRECT,-1,"정답");}
}
